def strategy(history, rng):
    n = len(history)

    # Cooperative opening, then adaptive retaliation/forgiveness.
    if n == 0:
        return 'C'

    # Count outcomes
    cc = cd = dc = dd = 0
    for me, opp in history:
        if me == 'C' and opp == 'C':
            cc += 1
        elif me == 'C' and opp == 'D':
            cd += 1
        elif me == 'D' and opp == 'C':
            dc += 1
        else:
            dd += 1

    my_score = 3 * cc + 0 * cd + 5 * dc + 1 * dd
    opp_score = 3 * cc + 5 * cd + 0 * dc + 1 * dd

    # Fast cooperative lock-in if opponent is consistently cooperative.
    opp_c = cc + cd
    opp_d = dc + dd
    if opp_c >= n and n >= 3:
        return 'C'

    # If opponent almost always cooperates recently, keep cooperating.
    if n >= 8:
        recent = history[-8:]
        rcc = sum(1 for me, opp in recent if opp == 'C')
        if rcc >= 7:
            return 'C'
        if rcc <= 1:
            return 'D'

    # Early game: mostly cooperate, but if opponent defected immediately, retaliate.
    if n <= 2:
        if any(opp == 'D' for me, opp in history):
            return 'D'
        return 'C'

    # Tit-for-tat style base with slight forgiveness.
    last_me, last_opp = history[-1]
    if last_opp == 'C':
        # If we're far behind, defect occasionally to catch up.
        if opp_score - my_score > 10 and rng.random() < 0.35:
            return 'D'
        return 'C'
    else:
        # Opponent just defected. Retaliate, but forgive if they have been nice overall.
        if cd > 0 and cc > cd:
            # They defected but we have a cooperative majority history.
            if rng.random() < 0.25:
                return 'C'
        return 'D'

